/**
 * The demo replays a recorded, real run (generated by `npm run make-demo` from cached model answers),
 * so visitors see what Omigator does without an API key. Nothing in it is simulated except the timing.
 */

import type { DatasetResult, Explanation, Protocol, RunManifest } from '../core';

export interface DemoRecording {
  title: string;
  recordedAt: string;
  note: string;
  protocol: Protocol;
  retmax: number;
  manifest: RunManifest;
  /** In ranking order, without explanations. */
  results: DatasetResult[];
  /** Recorded explanations, shown when the visitor asks for one. */
  explanations: Record<string, Explanation>;
  /** Reference list (the meta-analysis' included GSEs) for the evaluation tab. */
  gold: string[];
}

export async function loadDemo(): Promise<DemoRecording> {
  const res = await fetch(`${import.meta.env.BASE_URL}demo/hypoxia.json`);
  if (!res.ok) throw new Error(`Demo data not found (HTTP ${res.status}).`);
  return res.json();
}
